import pathlib,json,re,hashlib,pandas as pd,numpy as np
REPO=pathlib.Path('/home/boltzmann13/IMRAN/NOV26/cirspr-sci-env');ROOT=pathlib.Path((REPO/'05_validated_benchmarks/CURRENT.txt').read_text());x=pd.read_csv(ROOT/'data/CRISPRoffT_allframe.tsv',sep='\t',low_memory=False)
# Freeze selection before scoring: WT SpCas9, standard sgRNA, human, cellular targeted sequencing,
# explicit nominal0.1% sensitivity and an assayed boolean label, not mere biochemical nomination.
y=x[(x.Cas9_type=='SpCas9')&(x.gRNA=='sgRNA')&(x.Species=='Homo sapiens')&x.Validation.notna()&x.Identity.eq('OFF')].copy()
y['indel_corrected_percent']=pd.to_numeric(y['Indel_accu%'],errors='coerce');y['nominal_01pct_sensitivity']=y.Targeted_method.fillna('').str.contains(r'0\.1\s*%',regex=True)
y['guide_sequence']=y.Guide_sequence.str[:20];y['guide_PAM']=y.Guide_sequence.str[20:]
y['valid_pair']=y.guide_sequence.str.fullmatch('[ACGT]{20}').fillna(False)&y.Protospacer_sequence.str.fullmatch('[ACGT]{20}').fillna(False)&y.PAM.str.fullmatch('[ACGT]{3}').fillna(False)&y.guide_PAM.str.fullmatch('[ACGT]GG').fillna(False)
y['cellular_targeted']=y.Targeted_location.fillna('').str.contains('cell',case=False)
y['sequence_consistency']=(y.Target_sequence==y.Protospacer_sequence+y.PAM)
y['eligible']=y.indel_corrected_percent.notna()&y.nominal_01pct_sensitivity&y.valid_pair&y.cellular_targeted&y.sequence_consistency
z=y[y.eligible].copy();z['positive']=z.indel_corrected_percent>.1
# One fixed assay/cell/delivery/time stratum, largest measured eligible cohort; no score-based selection.
summary=z.groupby(['PMID','Technology_others','Targeted_method'],dropna=False).agg(n=('positive','size'),positives=('positive','sum')).reset_index();summary['negatives']=summary.n-summary.positives
summary=summary[(summary.n>=100)&(summary.positives>0)&(summary.negatives>0)].sort_values(['n','PMID','Technology_others'],ascending=[False,True,True])
summary.to_csv(ROOT/'data/specificity_eligible_strata.csv',index=False);assert len(summary)>0,'No defensible positive/negative assay stratum'
sel=summary.iloc[0];c=z[(z.PMID==sel.PMID)&(z.Technology_others==sel.Technology_others)&(z.Targeted_method==sel.Targeted_method)].copy()
keys=['On_target_site','Guide_sequence','Target_sequence','chr','start','end','Strand']
conflict=c.groupby(keys,dropna=False).indel_corrected_percent.nunique();assert not (conflict>1).any(),'Conflicting duplicate assays require explicit resolution';c=c.drop_duplicates(keys)
c['candidate_id']=['CFD_site_%06d'%i for i in range(len(c))];c['off_target_sequence']=c.Protospacer_sequence;c['mismatch_count']=[sum(a!=b for a,b in zip(q,t)) for q,t in zip(c.guide_sequence,c.off_target_sequence)];c['workflow_enumerable_ungapped_NGG_le3mm']=c.PAM.str[1:].eq('GG')&c.mismatch_count.le(3)
c.to_csv(ROOT/'data/specificity_assayed_cohort.csv',index=False);c[['candidate_id','guide_sequence','off_target_sequence','PAM']].rename(columns={'PAM':'pam'}).to_csv(ROOT/'data/CFD_assayed_inputs.csv',index=False)
y.to_csv(ROOT/'data/specificity_intake_audit.csv',index=False)
protocol={'model':'CFD2016 SpCas9','source_url':'https://ccsm.uth.edu/CRISPRoffT/table_summary/allframe_update_addEpige.txt','source_sha256':hashlib.sha256((ROOT/'data/CRISPRoffT_allframe.tsv').read_bytes()).hexdigest(),'stratum':{k:str(sel[k]) for k in ['PMID','Technology_others','Targeted_method']},'selected_before_scoring':True,'rows':len(c),'guides':c.On_target_site.nunique(),'positives':int(c.positive.sum()),'negatives':int((~c.positive).sum()),'positive_definition':'background-corrected Indel_accu% >0.1; strict boundary matches selected assay description; >=0.1 sensitivity analysis reported separately','negative_definition':'experimentally assayed boolean-Validation rows with finite corrected indel <=0.1%; unassayed candidates, PCR failures and missing/censored values excluded','detection_limit':'study/database nominal0.1% targeted-sequencing sensitivity; no read-depth-based site-specific LoD can be independently established from summary table','nuclease':'WT SpCas9 only','guide_context':'20nt standard sgRNA with intended NGG; no HF variants, prime/base editors or crRNA modifications pooled','score_scope':'all eligible ungapped assayed20nt pairs, with native target-PAM CFD scoring; prior workflow NGG/<=3mm coverage reported separately','training_exclusion':'CFD learned mismatch/PAM rules derive from Doench2016 mismatch screen; no retraining/tuning here. Selected independent study PMID recorded; if26780180 is selected, block as training-source overlap.','metrics':'average precision, trapezoid PR-AUC, per-guide recall@K on assayed candidate universe, precision@K; no genome-wide or clinical recall claim','population':'no variant panels, phased haplotypes, bulges or structural variants evaluated','important_limit':'selection conditions on nomination/assay testing; summary-table labels do not create a representative genome-wide negative set'}
assert str(sel.PMID)!='26780180';(ROOT/'protocols/specificity_CFD.json').write_text(json.dumps(protocol,indent=2));print(json.dumps(protocol,indent=2));print(c[['Source','Targeted_source','Targeted_delivery','Targeted_Time']].drop_duplicates().to_string(index=False))
